changeSet.sql:
SET @exist := (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS 
    WHERE TABLE_SCHEMA = DATABASE() 
    AND TABLE_NAME = 'agreements' 
    AND CONSTRAINT_NAME = 'fk_agreement_template');
SET @sqlstmt := IF(@exist > 0, 'ALTER TABLE agreements DROP FOREIGN KEY fk_agreement_template', 'SELECT 1');
PREPARE stmt FROM @sqlstmt; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @exist := (SELECT COUNT(*) FROM information_schema.statistics 
    WHERE table_schema = DATABASE() 
    AND table_name = 'agreements' 
    AND index_name = 'idx_incoming_template');
SET @sqlstmt := IF(@exist = 0, 'CREATE INDEX idx_incoming_template ON agreements (incoming_settlement_template_id)', 'SELECT 1');
PREPARE stmt FROM @sqlstmt; EXECUTE stmt; DEALLOCATE PREPARE stmt;

